#!/bin/bash
# aplicar.sh IP : escribe la regla como root (sin archivo temporal de usuario), valida con sshd -t, recarga; rollback si falla
ip=$1
python3 ~/mesh-run/hrun.py $ip 'S(){ echo Utec@2026 | sudo -S -p "" "$@"; }; F=/etc/ssh/sshd_config.d/90-bloquear-001.conf; S sh -c "echo  | base64 -d > $F.tmp && chmod 644 $F.tmp && mv $F.tmp $F"; if S sshd -t && S sshd -T | grep -qi "^denyusers"; then S systemctl reload ssh && echo APLICADO: $(S sshd -T | grep -i "^denyusers"); else S rm -f $F $F.tmp; S systemctl reload ssh; echo ROLLBACK; fi'
